You can to override the rem setting by adding something like:

html { font-size: 16px !important // whatever you like }

to `custom-canvas.css` - this file gets injected at the top level of each Embeddable.

In Embeddable, each component runs in its own instance of the shadow DOM and we don't have a container element around all of them that's defined in the component repo. However, you can create your own wrapper around your <em-beddable> code and style it however you like, and then adjust these lines in index.css to remove the border/padding/etc from every component:
:host(.inside-card) {
  /*  box-shadow: 0px 1px 4px rgba(28, 28, 33, 0.2);*/
  border-radius: 12px;
  padding: 15px !important;
  border: 1px solid #ddd;
}
Which would yield a similar result.

For the limit functionality, unset limits default to 100:
![Screenshot 2024-12-12 at 10.59.09|225x179, 100%](/img/faq/bb59a7e404b10952e0f43f0dbedc2b537509c23c.png)
You can get around this by setting the limit in the loadData function that's in your emb.ts file, so for example if you don't want to give the user an option to adjust the limit via an input, you could do something like:

```
   results: loadData({
        from: inputs.ds,
        limit: 5000,
        dimensions: [inputs.xAxis],
        measures: [inputs.metric],
      }),
```
But if you do have an input that allows the end user to set their own limit, you could do:

```
     results: loadData({
        from: inputs.ds,
        limit: inputs.limit || 5000,
        dimensions: [inputs.xAxis],
        measures: [inputs.metric],
      }),
```

In Embeddable, you can customize your import paths (e.g. have absolute paths in your React components) and add path aliases.

To enable this, you need to add it in two places:

```
// embeddable.config.ts

{
     ...
      viteConfig: {
        resolve: {
          alias: {
            "@/custom-alias": path.resolve(__dirname, "src/custom-alias"),
          },
        },
      },
    }
```
```
// tsconfig.json (TypeScript configuration file placed in the root of the repository)

{
  "compilerOptions": {
    ...
    "paths": {
      "@/custom-alias/*": ["src/custom-alias/*"]
    }
  }
}
```
And finally, this will enable imports like
```
import SomeComponent from "@/custom-alias/Component"
```
Additionally, the following is required for __dirname and to work in the `path.resolve(__dirname, '../src/components')` :
```
import path from 'path'; import { fileURLToPath } from 'url'; // Get the equivalent of __dirname for ES modules const __filename = fileURLToPath(import.meta.url); const __dirname = path.dirname(__filename);
```

When using the MUI select component in Embeddable, you might notice the popover may not render correctly. There are 2 options for using the Material UI select component:

1. Make usage of the native MUI components (in this case the NativeSelect).
2. Use the normal MUI Select, and try to restyle it.

These are example files:

```
Wrapper

import createCache from '@emotion/cache';
import { CacheProvider } from '@emotion/react';
import { CssBaseline, ThemeProvider, createTheme } from '@mui/material';
import { LocalizationProvider } from '@mui/x-date-pickers';
import { AdapterDateFns } from '@mui/x-date-pickers/node/AdapterDateFns/index.js';
import React from 'react';

const ThemeWrapper = ({ children }: any) => {
  const ref = React.useRef<HTMLDivElement>(null);
  const [cache, setCache] = React.useState<any>();
  const [theme, setTheme] = React.useState<any>();

  React.useEffect(() => {
    if (ref.current === null) return;

    const shadowContainer = ref.current.getRootNode() as ShadowRoot;
    const shadowRootElement = document.createElement('div');
    shadowContainer.appendChild(shadowRootElement);

    const cache = createCache({
      key: 'css',
      prepend: true,
      container: shadowContainer
    });

    setCache(cache);

    const theme = createTheme({
      components: {
        // If not using the NativeSelect, uncomment this block
        // MuiPopover: {
        //   defaultProps: {
        //     container: shadowRootElement
        //   }
        // },
        // MuiPopper: {
        //   defaultProps: {
        //     container: shadowRootElement
        //   }
        // }
      }
    });

    setTheme(theme);
  }, [ref]);

  if (!cache || !theme) return <div ref={ref}>loading...</div>;

  return (
    <LocalizationProvider dateAdapter={AdapterDateFns}>
      <CacheProvider value={cache}>
        <ThemeProvider theme={theme}>
          <CssBaseline />
          {children}
        </ThemeProvider>
      </CacheProvider>
    </LocalizationProvider>
  );
};

export default ThemeWrapper;

```

