The general idea is to `onClick` take the values of two variables and set them as the values of two other variables. The destination variables may be defined outside of the scope of this button, e.g. declared manually as part of the dashboard or declared by some other component on the dashboard.

Solution:

```jsx
import { EmbeddedComponentMeta, defineComponent } from '@embeddable.com/react';
import { Value } from '@embeddable.com/core';

import Component from './index';

export const meta: EmbeddedComponentMeta = {
  name: 'BasicButtonComponent',
  label: 'Basic Button',
  inputs: [
    {
      name: 'label',
      type: 'string',
      label: 'Label',
      description: 'The text on the button'
    },
  ],
  events: [
    {
      name: 'onClick',
      label: 'Click',
      properties: []
    }],
};

type Inputs = {
  label: string;
}

export default defineComponent<Inputs>(Component, meta, {
  props: (inputs) => {
    return {
      ...inputs
    };
  },
  events: {
    onClick: (e) => ({ })
  }
});
```

